WITH flattened_attrs AS (SELECT id, customer_id, created_at, items, ship_to, attributes['gift'] AS gift, EXISTS(items, li -> li.price > 100) AS has_premium_item FROM carts) SELECT customer_id, COUNT(DISTINCT gift) AS distinct_gifts, COUNT(DISTINCT gift) AS distinct_gifts_2, MAX(created_at) AS last_seen, MAX(created_at) AS ended_at, COUNT(*) AS num_rows, COUNT(DISTINCT gift) AS distinct_gifts_3 FROM flattened_attrs GROUP BY customer_id HAVING COUNT(DISTINCT gift) > 1 ORDER BY distinct_gifts_3 DESC
